/**
 * Return the primer ids tagged on a scenario, deduplicated, preserving order.
 */
export function getPrimerIdsForScenario(scenario) {
  if (!scenario || !Array.isArray(scenario.primerTags)) return [];
  const seen = new Set();
  const ids = [];
  for (const tag of scenario.primerTags) {
    if (typeof tag === 'string' && !seen.has(tag) && HISTORICAL_PRIMERS[tag]) {
      seen.add(tag);
      ids.push(tag);
    }
  }
  return ids;
}

/**
 * Hydrate a scenario's primerTags into the full primer objects.
 */
export function resolvePrimersForScenario(scenario) {
  return getPrimerIdsForScenario(scenario).map((id) => HISTORICAL_PRIMERS[id]);
}

/**
 * Compact context block for the local Ollama prompt. Surfaces only the
 * power_analysis paragraph (the structural framing) plus a short sourceNotes
 * line so the model has ground-truth context for the tagged topics without
 * being flooded with the full primer body.
 */
export function buildPrimerContextNote(scenario) {
  const primers = resolvePrimersForScenario(scenario);
  if (!primers.length) return '';
  const lines = primers.map(
    (primer) => `- ${primer.topic}: ${primer.power_analysis} Sources: ${primer.sourceNotes}`,
  );
  return `\n\nHistorical primers tagged on this turn (ground truth — do not contradict):\n${lines.join('\n')}`;
}
